import { ArrowUpRightIcon } from "lucide-react";
import type { ReactNode } from "react";
import { MarketingSection } from "@/components/marketing-section";
import { Button } from "@/components/ui/button";

export interface Cta12Action {
  href?: string;
  label: string;
}

export interface Cta12Props {
  className?: string;
  primaryCta?: Cta12Action;
  secondaryCta?: Cta12Action;
  title?: string;
}

function PrimaryCtaButton({ action }: { action: Cta12Action }) {
  const content = (
    <>
      {action.label}
      <ArrowUpRightIcon data-icon="inline-end" />
    </>
  );

  if (action.href) {
    return (
      <Button
        className="rounded-full"
        nativeButton={false}
        render={<a href={action.href} />}
        variant="outline"
      >
        {content}
      </Button>
    );
  }

  return (
    <Button className="rounded-full" type="button" variant="outline">
      {content}
    </Button>
  );
}

function ActionLink({
  action,
  className,
  children,
}: {
  action: Cta12Action;
  className?: string;
  children: ReactNode;
}) {
  if (action.href) {
    return (
      <Button
        className={className}
        nativeButton={false}
        render={<a href={action.href} />}
        variant="link"
      >
        {children}
      </Button>
    );
  }

  return (
    <Button className={className} type="button" variant="link">
      {children}
    </Button>
  );
}

export function Cta12({
  title = "Ship 10x Faster with Nice UI",
  primaryCta = { href: "#", label: "Get Started" },
  secondaryCta = { href: "#", label: "Try it now" },
  className,
}: Cta12Props) {
  return (
    <MarketingSection className={className}>
      <section className="relative flex items-center justify-center px-6 py-16">
        <div className="relative px-10 py-12 sm:px-16 sm:py-14">
          <div className="pointer-events-none absolute inset-x-0 top-0 h-px bg-border" />
          <div className="pointer-events-none absolute inset-x-0 bottom-0 h-px bg-border" />
          <div className="pointer-events-none absolute inset-y-[-18%] left-0 w-px bg-border" />
          <div className="pointer-events-none absolute inset-y-[-18%] right-0 w-px bg-border" />

          <div className="flex flex-col items-center gap-6 text-center">
            <h2 className="font-display-heading text-2xl [text-shadow:0_0_32px_--theme(--color-foreground/.25)] md:text-4xl">
              {title}
            </h2>
            <div className="flex items-center gap-4">
              {secondaryCta ? (
                <ActionLink
                  action={secondaryCta}
                  className="font-medium text-sm hover:underline"
                >
                  {secondaryCta.label}
                </ActionLink>
              ) : null}
              {primaryCta ? <PrimaryCtaButton action={primaryCta} /> : null}
            </div>
          </div>
        </div>
      </section>
    </MarketingSection>
  );
}
